"""Render evidence tables; final conclusions require manual reconciliation."""
from pathlib import Path
import json,sys
r=Path(sys.argv[1]);data=json.loads((r/'analysis.json').read_text());rows=data['results'];auditpath=r/'window-rate-audit.json';audits={x['case']:x for x in json.loads(auditpath.read_text())['cases']}if auditpath.exists()else{};lines=['# Isolated Opt79 measurement tables','','Generated from analysis.json and timestamp-matched window-rate-audit.json. These are measurements, not an automatic production-readiness declaration.','',
'| Case | Cameras × FPS | Matched counter inference FPS range | Active rate criterion | Original harness | RAM p95 MiB | CPU p95 cores | CPU package max °C | Scene API gap p95 s |',
'|---|---:|---:|---|---|---:|---:|---:|---:|']
def fmt(v):return '—' if v is None else f'{v:.2f}'
for x in rows:
 c=x['configuration'];audit=audits.get(x['case'],{});camera_rates=audit.get('cameras',{});rates=[v['cumulative_fps']['inference_frames']for v in camera_rates.values()if 'cumulative_fps'in v];rates=rates if len(rates)==c['cameras']else[];gaps=[v['api_interarrival_seconds']['p95']for v in x.get('scene_cadence',{}).values()if v['api_interarrival_seconds']['p95']is not None]
 ratepass=audit.get('all_active_windows_passed');cum_pass=bool(camera_rates)and all(v.get('cumulative_active_95pct_passed')for v in camera_rates.values())
 criterion='timing incomplete'if ratepass is None else'PASS rate only'if ratepass and cum_pass else'below active rate criterion'
 verdict=('INVALID TEST INPUT'if x.get('invalid_test_configuration')or x.get('invalid_test_fixture')else None)or('INVALID POWER TRANSITION'if x.get('invalid_power_transition')else None)or x.get('abort')or criterion
 lines.append(f"| {x['case']} | {c['cameras']} × {c['fps']} | {fmt(min(rates))+'–'+fmt(max(rates))if rates else '—'} | {verdict} | {audit.get('harness_passed','—')} | {fmt(x.get('container_memory_mb',{}).get('p95'))} | {fmt(x.get('container_cpu_cores',{}).get('p95'))} | {fmt(x.get('resources',{}).get('cpu_package_C',{}).get('max'))} | {fmt(max(gaps))if gaps else '—'} |")
lines+=['','## Scope and interpretation','','a2 is stock-power controlled replay. a3 uses short-term65W but turbo enabled. a4 disables CPU turbo and retains short-term65W; sustained limit45W throughout. Transitional runs and attempt1 source-mapping errors are invalid for capacity. All application profiles keep scene search on every camera. Quiet admitted/safety-sweep behavior is separate from continuous active inference.','', 'Matched rates use exact counter tuples and camera snapshot timestamps from the independent1Hz observer. Dividing cached counters by HTTP poll intervals can fabricate FPS dips. An incomplete timing match remains unqualified. Fault, quiet and negative-input cases are not continuous-active capacity claims even when their rate column is below target.','', 'RAM/CPU table statistics come from steady harness snapshots. Temperature includes startup. Scene gaps here include startup/fault/shutdown and are diagnostic, not an automatic cadence SLA verdict. Independent marker latency and steady-source cadence must be reconciled separately.','', 'A rate candidate still requires freshness, every-camera scene coverage, complete outputs, no fatal native errors, and headroom before any deployment recommendation. API receiver validates CV handoff only; downstream Management is outside scope.']
(r/'MEASUREMENT_TABLES.md').write_text('\n'.join(lines)+'\n')
print(r/'MEASUREMENT_TABLES.md')
